module radix2_div (
    input clk, 
    input rst, 
    input sign, 
    input [7:0] dividend, 
    input [7:0] divisor, 
    input opn_valid, 
    output reg res_valid, 
    output reg [15:0] result
);
    reg [7:0] dividend_reg, divisor_reg;
    reg [7:0] remainder, quotient;
    reg [3:0] cnt;
    reg [15:0] SR;
    reg [8:0] NEG_DIVISOR;

    always @(posedge clk or negedge rst) begin
        if(!rst) begin
            cnt <= 4'd0;
            res_valid <= 1'b0;
            SR <= 16'd0;
            NEG_DIVISOR <= 9'd0;
        end else begin
            if(opn_valid && !res_valid) begin
                dividend_reg <= dividend;
                divisor_reg <= divisor;
                remainder <= 8'd0;
                quotient <= 8'd0;
                cnt <= 4'd1;
                NEG_DIVISOR <= (~{1'b0, divisor_reg[7], divisor_reg} + 1);
                SR <= {{8{1'b0}}, {1'b0, dividend_reg[7], dividend_reg}} << 1;
            end else if(cnt != 4'd0) begin
                if(cnt[3]) begin
                    cnt <= 4'd0;
                    res_valid <= 1'b1;
                    SR <= {remainder, quotient};
                end else begin
                    cnt <= cnt + 4'd1;
                    remainder <= ({NEG_DIVISOR[8], SR[15:8]} >> 1);
                    quotient <= (NEG_DIVISOR[8])? ((SR[15:8] + NEG_DIVISOR)>>1) : (SR[15:8]>>1);
                    SR <= {remainder, quotient} << 1;
                end
            end else begin
                res_valid <= 1'b0;
            end
        end
    end

    always @(posedge clk) begin
        if(res_valid) begin
            result <= SR;
        end
    end
endmodule
